effect.shader:
const mat4 bayerMatrix = mat4(
0.0, 8.0, 2.0, 10.0,
12.0, 4.0, 14.0, 6.0,
3.0, 11.0, 1.0, 9.0,
15.0, 7.0, 13.0, 5.0
) / 16.0;
float getDither(vec2 pos) {
int x = int(mod(pos.x, 4.0));
int y = int(mod(pos.y, 4.0));
if (x == 0) {
if (y == 0) return bayerMatrix[0][0];
if (y == 1) return bayerMatrix[0][1];
if (y == 2) return bayerMatrix[0][2];
return bayerMatrix[0][3];
} else if (x == 1) {
if (y == 0) return bayerMatrix[1][0];
if (y == 1) return bayerMatrix[1][1];
if (y == 2) return bayerMatrix[1][2];
return bayerMatrix[1][3];
} else if (x == 2) {
if (y == 0) return bayerMatrix[2][0];
if (y == 1) return bayerMatrix[2][1];
if (y == 2) return bayerMatrix[2][2];
return bayerMatrix[2][3];
} else {
if (y == 0) return bayerMatrix[3][0];
if (y == 1) return bayerMatrix[3][1];
if (y == 2) return bayerMatrix[3][2];
return bayerMatrix[3][3];
}
}
float colorDist(vec3 c1, vec3 c2) {
return distance(c1, c2);
}
void main() {
vec2 uv = acScreenNorm;
float resScale = acScreenSize.y / 1080.0;
vec2 pixelSize = (mosaic * resScale) / acScreenSize;
vec2 blockUv = floor(uv / pixelSize) * pixelSize + (pixelSize * 0.5);
vec4 src = texture2DCv(inputImg.texture, blockUv);
vec3 col = src.rgb;
float ditherValue = getDither(uv * acScreenSize / (mosaic * resScale));
col += (ditherValue - 0.5) * dithering;
vec3 palette[7];
palette[0] = color1.rgb; palette[1] = color2.rgb; palette[2] = color3.rgb;
palette[3] = color4.rgb; palette[4] = color5.rgb; palette[5] = color6.rgb;
palette[6] = color7.rgb;
vec3 closest = palette[0];
float minDist = colorDist(col, palette[0]);
for(int i = 1; i < 7; i++) {
float d = colorDist(col, palette[i]);
if (d < minDist) {
minDist = d;
closest = palette[i];
}
}
vec4 finalColor = vec4(closest, src.a);
vec4 original = texture2DCv(inputImg.texture, uv);
gl_FragColor = mix(original, finalColor, blending);
}
